using System;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Volo.Abp.Internal.Telemetry;
using Volo.Abp;

namespace Volo.Abp.Tests
{
    public class AbpApplicationBaseTelemetryTests
    {
        private class TestApplication : AbpApplicationBase
        {
            public TestApplication(IServiceProvider serviceProvider) 
                : base(typeof(TestApplication), new ServiceCollection(), null)
            {
                SetServiceProvider(serviceProvider);
            }

            public new Task InitializeTelemetryTracking() => base.InitializeTelemetryTracking();
        }

        [Fact]
        public async Task InitializeTelemetryTracking_CallsAddActivityAsync()
        {
            // Arrange
            var telemetryServiceMock = new Mock<ITelemetryService>();
            telemetryServiceMock
                .Setup(t => t.AddActivityAsync(ActivityNameConsts.ApplicationRun))
                .Returns(Task.CompletedTask)
                .Verifiable();

            var serviceCollection = new ServiceCollection();
            serviceCollection.AddTransient(_ => telemetryServiceMock.Object);

            var serviceProvider = serviceCollection.BuildServiceProvider();

            var app = new TestApplication(serviceProvider);

            // Act
            await app.InitializeTelemetryTracking();

            // Assert
            telemetryServiceMock.Verify(t => t.AddActivityAsync(ActivityNameConsts.ApplicationRun), Times.Once);
        }
    }
}
```

